compile.workshop:
variables {
    global:
        0: j
        1: h
        2: k
    player:
        0: p
}

rule ("Initialize global variables") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(j, 5);
        Set Global Variable(k, 0.0);
    }
}

rule ("Initialize player variables") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Player Variable(Event Player, p, 7);
    }
}

rule ("r") {
    event {
        Ongoing - Global;
    }
    actions {
        Disable Inspector Recording;
    }
}

